using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using System;using System.Linq;using Object=UnityEngine.Object;
public static class SetupLawnmower {
 static Transform Pivot(string name,Transform parent,Vector3 world){var t=new GameObject(name).transform;t.SetParent(parent,false);t.position=world;return t;}
 static void Box(Transform p,string name,Vector3 center,Vector3 size){var g=new GameObject(name);g.transform.SetParent(p,false);var c=g.AddComponent<BoxCollider>();c.center=center;c.size=size;}
 public static string Main(){if(Application.isPlaying)throw new Exception("Edit mode required");if(GameObject.Find("Lawnmower with trailer - driveable"))throw new Exception("Already prepared");var original=GameObject.Find("Lawnmower");
 System.IO.Directory.CreateDirectory("output/Lawnmower/Backups");if(!EditorSceneManager.SaveScene(original.scene,"output/Lawnmower/Backups/Gameplay.before-mower.unity",true))throw new Exception("Backup failed");
 var group=new GameObject("Lawnmower with trailer - driveable");group.SetActive(false);group.transform.position=original.transform.position;Undo.RegisterCreatedObjectUndo(group,"Prepare lawnmower and trailer");
 var mower=Pivot("Lawnmower - driveable",group.transform,original.transform.position);var model=Object.Instantiate(original,mower).transform;model.name="Lawnmower visuals";model.SetPositionAndRotation(original.transform.position,original.transform.rotation);if(PrefabUtility.IsPartOfPrefabInstance(model))PrefabUtility.UnpackPrefabInstance(model.gameObject,PrefabUnpackMode.Completely,InteractionMode.AutomatedAction);
 var trailerModel=model.Find("Tow_Trailer");var trailer=Pivot("Tow_Trailer - jointed",group.transform,trailerModel.position);trailerModel.SetParent(trailer,true);
 foreach(var c in group.GetComponentsInChildren<Collider>(true))Object.DestroyImmediate(c);
 Transform Find(string n)=>model.GetComponentsInChildren<Transform>(true).First(t=>t.name==n);
 Transform Wheel(string n,Transform parent){var old=Find(n);var p=Pivot(n+" axle",parent,old.position);old.SetParent(p,true);return p;}
 var left=Find("TFP_Lawnmower_01A_Wheel_F.L");var right=Find("TFP_Lawnmower_01A_Wheel_F.R");var sl=Pivot("Front left steering",mower,left.position);var sr=Pivot("Front right steering",mower,right.position);
 var fl=Wheel(left.name,sl);var fr=Wheel(right.name,sr);var rl=Wheel("TFP_Lawnmower_01A_Wheel_R.L",mower);var rr=Wheel("TFP_Lawnmower_01A_Wheel_R.R",mower);
 var rig=mower.gameObject.AddComponent<BicycleController>();rig.motorDriven=true;rig.steering=sl;rig.frontWheel=fl;rig.rearWheel=rl;rig.riderView=Pivot("Driver view",mower,mower.TransformPoint(new Vector3(0,1.75f,-.6f)));rig.SetRidingCamera(Vector3.zero,8);rig.cargoSlots=new Transform[0];rig.maximumSteeringAngle=28;rig.dismountSideDistance=1.5f;rig.dismountLongitudinalDistance=2.5f;
 var cc=mower.GetComponent<CharacterController>();cc.height=1.45f;cc.radius=.48f;cc.center=new Vector3(0,.75f,-.3f);cc.skinWidth=.025f;cc.stepOffset=.15f;cc.slopeLimit=35;
 Box(mower,"Parked mower body",new Vector3(.1f,.8f,-.45f),new Vector3(1.4f,1.4f,2.9f));
 var engine=mower.gameObject.AddComponent<MotorollerController>();using(var so=new SerializedObject(engine)){so.FindProperty("vehicleName").stringValue="lawnmower";so.FindProperty("maximumSpeed").floatValue=5;so.FindProperty("acceleration").floatValue=1.8f;so.FindProperty("brakingDeceleration").floatValue=6;so.FindProperty("wheelRadius").floatValue=.24f;so.FindProperty("wheelbase").floatValue=1.56f;so.FindProperty("collisionCenter").vector3Value=new Vector3(.1f,.85f,-.45f);so.FindProperty("collisionHalfExtents").vector3Value=new Vector3(.68f,.6f,1.48f);so.ApplyModifiedPropertiesWithoutUndo();}engine.Configure();
 var lawn=mower.gameObject.AddComponent<LawnmowerController>();lawn.frontRightSteering=sr;lawn.frontRightWheel=fr;lawn.rearRightWheel=rr;lawn.steeringWheel=Find("TFP_Lawnmower_01A_Steering_Wheel_LOD0");
 lawn.hitchTarget=Pivot("Tow hitch",mower,trailer.TransformPoint(new Vector3(0,.43f,0)));var hitch=Pivot("Kinematic hitch body",group.transform,lawn.hitchTarget.position);lawn.hitchBody=hitch.gameObject.AddComponent<Rigidbody>();lawn.hitchBody.isKinematic=true;lawn.hitchBody.interpolation=RigidbodyInterpolation.Interpolate;
 var body=trailer.gameObject.AddComponent<Rigidbody>();body.mass=100;body.centerOfMass=new Vector3(0,.55f,-2.7f);body.linearDamping=.1f;body.angularDamping=1;body.interpolation=RigidbodyInterpolation.Interpolate;body.collisionDetectionMode=CollisionDetectionMode.ContinuousDynamic;body.solverIterations=12;body.solverVelocityIterations=8;
 Box(trailer,"Trailer floor",new Vector3(0,.58f,-2.9f),new Vector3(1.8f,.16f,3));Box(trailer,"Trailer left side",new Vector3(-.94f,.95f,-2.9f),new Vector3(.12f,.65f,3.1f));Box(trailer,"Trailer right side",new Vector3(.94f,.95f,-2.9f),new Vector3(.12f,.65f,3.1f));Box(trailer,"Trailer front",new Vector3(0,.95f,-1.4f),new Vector3(1.8f,.65f,.12f));Box(trailer,"Trailer tailgate",new Vector3(0,.95f,-4.45f),new Vector3(1.8f,.65f,.12f));Box(trailer,"Drawbar",new Vector3(0,.43f,-.7f),new Vector3(.2f,.12f,1.4f));
 var joint=trailer.gameObject.AddComponent<ConfigurableJoint>();joint.connectedBody=lawn.hitchBody;joint.autoConfigureConnectedAnchor=false;joint.anchor=new Vector3(0,.43f,0);joint.connectedAnchor=Vector3.zero;joint.axis=Vector3.up;joint.secondaryAxis=Vector3.right;joint.xMotion=joint.yMotion=joint.zMotion=ConfigurableJointMotion.Locked;joint.angularXMotion=joint.angularYMotion=joint.angularZMotion=ConfigurableJointMotion.Limited;joint.lowAngularXLimit=new SoftJointLimit{limit=-70};joint.highAngularXLimit=new SoftJointLimit{limit=70};joint.angularYLimit=new SoftJointLimit{limit=20};joint.angularZLimit=new SoftJointLimit{limit=15};joint.projectionMode=JointProjectionMode.PositionAndRotation;joint.projectionDistance=.1f;joint.projectionAngle=5;lawn.trailerJoint=joint;
 lawn.trailerWheels=new WheelCollider[2];lawn.trailerWheelVisuals=new Transform[2];for(int i=0;i<2;i++){var visual=trailerModel.GetComponentsInChildren<Transform>().First(t=>t.name=="TFP_Tow_Trailer_01A_Wheel."+(i==0?"L":"R"));var pivot=Pivot("Trailer wheel visual "+i,trailer,visual.position);visual.SetParent(pivot,true);var wp=Pivot("Trailer suspension "+i,trailer,pivot.position+Vector3.up*.12f);var w=wp.gameObject.AddComponent<WheelCollider>();w.radius=.42f;w.mass=12;w.suspensionDistance=.24f;w.suspensionSpring=new JointSpring{spring=12000,damper=1800,targetPosition=.5f};var f=w.sidewaysFriction;f.stiffness=1.5f;w.sidewaysFriction=f;lawn.trailerWheels[i]=w;lawn.trailerWheelVisuals[i]=pivot;}
 var pin=trailerModel.GetComponentsInChildren<Transform>().First(t=>t.name=="TFP_Tow_Trailer_01A_Pin_LOD0");pin.gameObject.SetActive(false);
 original.SetActive(false);group.SetActive(true);System.IO.Directory.CreateDirectory("Assets/Models/Lawnmower/Driveable");AssetDatabase.Refresh();PrefabUtility.SaveAsPrefabAssetAndConnect(group,"Assets/Models/Lawnmower/Driveable/Lawnmower_With_Trailer.prefab",InteractionMode.AutomatedAction);AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(group.scene);Selection.activeGameObject=group;return "Prepared mower with articulated rigidbody trailer and preserved LODs";
 }}
